/* ================= B4 · Review and publishing ================= */
const REV_TABS = [['queue', 'Review queue', c => c.stage === 'Report submitted' || c.stage === 'In review'], ['approved', 'Approved', c => c.stage === 'Approved'], ['scheduled', 'Scheduled', c => c.stage === 'Scheduled'], ['held', 'Held back', c => c.stage === 'Held back'], ['published', 'Published', c => c.stage === 'Published'], ['tracker', 'Tracker', c => ['Approved', 'Scheduled', 'Held back', 'Published'].includes(c.stage)]];
const reviewers = () => S.team.filter(t => (t.role === 'Reviewer' || t.role === 'Supervisor' || t.role === 'Admin') && t.status === 'Active');
OPEN_HOOKS['reviews/report'] = (id) => { S.ui.revId = id; };
OPEN_HOOKS['reviews'] = (tab) => { S.ui.revTab = tab || 'queue'; };
const revCase = () => caseOf(S.ui.revId) || S.cases.find(c => c.stage === 'Report submitted') || S.cases[0];
screen('reviews', {
  t: 'Reviews & publishing', layout: 'app', ws: 'regulator', crumbs: ['Reviews & publishing'],
  render() {
    const tab = ui('revTab', 'queue'); const def = REV_TABS.find(t => t[0] === tab); const pf = ui('revProg', 'All');
    const all = S.cases.filter(c => pf === 'All' || c.prog === pf);
    const rows = all.filter(def[2]); const sel_ = ui('revSel', []).filter(id => rows.some(c => c.id === id));
    const cnt = k => all.filter(REV_TABS.find(t => t[0] === k)[2]).length;
    const ico = { queue: 'stamp', approved: 'check-circle', scheduled: 'calendar-blank', held: 'pause-circle', published: 'seal-check' };
    let tools = '';
    if (tab === 'queue') tools = btn('Assign reviewer', { size: 'sm', i: 'user-plus', act: 'revAssign', disabled: !sel_.length, test: 'rev-assign' });
    if (tab === 'approved') tools = btn('Schedule', { v: 'outline', size: 'sm', i: 'calendar-blank', act: 'pubDlg', arg: 'schedule', disabled: !sel_.length, test: 'pub-schedule' }) + btn(sel_.length ? `Publish ${sel_.length} now` : 'Publish now', { size: 'sm', i: 'paper-plane-tilt', act: 'pubDlg', arg: 'now', disabled: !sel_.length, test: 'pub-now' });
    if (tab === 'held') tools = btn('Review held reports', { v: 'outline', size: 'sm', act: 'revTab', arg: 'queue' });
    const sub = { queue: 'Reports submitted by firms. Assign a reviewer, then confirm, return or change outcomes.', approved: 'Approved reports. Publish now, or schedule a date.', scheduled: 'Reports that publish automatically on their date.', held: 'Reports that were not approved when publishing was scheduled. They publish once approved.', published: 'Organisations can see these reports and their findings.', tracker: 'Every approved report and what happened to it, including who has opened theirs.' }[tab];
    const head = `<tr>${['queue', 'approved'].includes(tab) ? `<th style="width:36px"><input type="checkbox" data-act="revSelAll" aria-label="Select all" ${sel_.length && sel_.length === rows.length ? 'checked' : ''}></th>` : ''}<th>Organisation</th><th>Programme</th><th>Firm</th><th class="num">Score</th>${tab === 'queue' ? '<th>Reviewer</th><th>Submitted</th>' : tab === 'tracker' ? '<th>Status</th><th>Opened by organisation</th>' : tab === 'scheduled' ? '<th>Publishes</th>' : tab === 'held' ? '<th>Why held</th>' : tab === 'published' ? '<th>Published</th><th>Opened</th>' : '<th>Approved</th>'}<th class="act-col"></th></tr>`;
    const body = rows.map(c => { const o = S.orgs[c.org]; const p = progOf(c.prog); const f = S.firms[c.firm]; const sc = c.score ?? caseScore(c); return `<tr class="click" data-act="open" data-arg="reviews/report:${c.id}" data-test="rev-${c.id}">${['queue', 'approved'].includes(tab) ? `<td><input type="checkbox" data-act="revSel" data-arg="${c.id}" ${sel_.includes(c.id) ? 'checked' : ''} aria-label="Select ${esc(o.name)}" data-test="rsel-${c.id}"></td>` : ''}<td>${orgCell(o, catLabel(o.type, o.tier))}</td><td class="small">${esc(p.name)}${p.publisher === 'firm' ? '<div class="cap muted">Publishing delegated to firm</div>' : ''}</td><td class="small">${f ? esc(f.name) : '—'}</td><td class="num"><b class="serif">${sc ?? '—'}</b></td>
      ${tab === 'queue' ? `<td class="small">${c.reviewer ? `<div class="row gap6">${av(initials(c.reviewer), 20)}${esc(c.reviewer)}</div>` : '<span class="cap" style="color:var(--warn-fg)">Not assigned</span>'}</td><td class="small muted">${esc(c.reportAt || '—')}</td>` : tab === 'tracker' ? `<td>${statusChip(c.stage)}${c.pubAt && c.stage === 'Scheduled' ? `<div class="cap muted">${fmtD(c.pubAt)}</div>` : ''}</td><td class="small">${c.stage === 'Published' ? (c.opened ? chip('Opened ' + (c.openedAt || ''), 'ok', 'eye') : chip('Not opened yet', 'neu')) : '—'}</td>` : tab === 'scheduled' ? `<td class="small">${fmtD(c.pubAt)}</td>` : tab === 'held' ? `<td class="small wrap">${esc(c.holdReason || 'Not approved in time')}</td>` : tab === 'published' ? `<td class="small muted">${esc(c.published || '')}</td><td>${c.opened ? chip('Opened', 'ok', 'eye') : chip('Not yet', 'neu')}</td>` : `<td class="small muted">${esc((c.approved || {}).when || '')}${(c.approved || {}).by ? ' · ' + esc(c.approved.by) : ''}</td>`}
      <td class="act-col">${ic('caret-right')}</td></tr>`; }).join('');
    const progs = [...new Set(S.cases.filter(c => REV_TABS[5][2](c) || REV_TABS[0][2](c)).map(c => c.prog))];
    return `${pageHead({ title: 'Reviews & publishing', sub: 'Check each firm\'s report, approve it, then publish it to the organisation.' })}
      <div class="card p0">${tabs(REV_TABS.map(([id, l]) => ({ id, label: l, test: 'rt-' + id, count: ['queue', 'approved', 'scheduled', 'held', 'published'].includes(id) ? cnt(id) : undefined })), tab, 'revTab')}
        <div class="tbl-tools wrap">${sel('rev-prog', [['All', 'All programmes'], ...progs.map(id => [id, progOf(id).name])], pf, { attrs: 'data-change="revProg" style="width:280px;height:36px"' })}<span class="small muted grow">${sub}</span>${sel_.length ? `<span class="small strong">${sel_.length} selected</span>` : ''}${tools}</div>
        <div class="tbl-wrap"><table class="tbl"><thead>${head}</thead><tbody>${body || `<tr><td colspan="8">${empty(ico[tab] || 'list', 'Nothing here', tab === 'queue' ? 'Reports appear when firms submit them.' : 'No reports in this list yet.')}</td></tr>`}</tbody></table></div></div>`;
  }
});
ACT.revTab = (t) => { S.ui.revTab = t; S.ui.revSel = []; render(); };
ACT.chg_revProg = (v) => { S.ui.revProg = v; S.ui.revSel = []; render(); };
ACT.revSel = (id, el, e) => { e && e.stopPropagation(); const s = ui('revSel', []); const i = s.indexOf(id); i >= 0 ? s.splice(i, 1) : s.push(id); render(); };
ACT.revSelAll = () => { const def = REV_TABS.find(t => t[0] === S.ui.revTab) || REV_TABS[0]; const pf = S.ui.revProg || 'All'; const rows = S.cases.filter(c => (pf === 'All' || c.prog === pf) && def[2](c)); S.ui.revSel = (S.ui.revSel || []).length === rows.length ? [] : rows.map(c => c.id); render(); };
ACT.revAssign = () => { const ids = S.ui.revSel || []; openDialog(`${dlgHead('Assign a reviewer', `${ids.length} report${ids.length === 1 ? '' : 's'}. The reviewer gets an email and the reports appear in their queue.`, 'user-plus')}<div class="col gap8">${reviewers().map((t, i) => `<label class="choice"><input type="radio" name="rv" value="${esc(t.name)}" class="sr" ${i === 1 ? 'checked' : ''}><span class="radio"></span>${av(t.ini)}<span class="grow"><b>${esc(t.name)}</b><br><span class="cap muted">${esc(t.role)} · ${esc(t.portfolio)}</span></span><span class="cap muted">${S.cases.filter(c => c.reviewer === t.name && c.stage === 'In review').length} in review</span></label>`).join('')}</div><div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Assign', { act: 'revAssignGo', test: 'ra-go' })}</div>`); };
ACT.revAssignGo = () => { const n = ($$('input[name=rv]').find(x => x.checked) || {}).value; if (!n) return; (S.ui.revSel || []).map(caseOf).forEach(c => { c.reviewer = n; c.stage = 'In review'; }); addAudit('Assigned reviewer', `${n} · ${(S.ui.revSel || []).length} reports`); const k = (S.ui.revSel || []).length; S.ui.revSel = []; closeDialog(); render(); toast(`${k} report${k === 1 ? '' : 's'} assigned to ${esc(n)}`, 'ok', 'user-plus'); };
/* publish dialog: now or on a date; unapproved reports in the same programme are held when scheduled */
ACT.pubDlg = (mode) => { const ids = S.ui.revSel || []; const cs = ids.map(caseOf); const progs = [...new Set(cs.map(c => c.prog))]; const pending = S.cases.filter(c => progs.includes(c.prog) && ['Report submitted', 'In review', 'Returned', 'Assessing', 'Submitted', 'In preview', 'Signed off', 'Answering'].includes(c.stage));
  openDialog(`${dlgHead(mode === 'now' ? 'Publish now' : 'Schedule publishing', `${ids.length} approved report${ids.length === 1 ? '' : 's'}. Organisations are emailed and see their report and findings.`, mode === 'now' ? 'paper-plane-tilt' : 'calendar-blank')}
    <div class="col gap12">${mode === 'schedule' ? field('Publish on', inp('pub-d', '2026-10-31', { type: 'date' }), { hint: 'Reports publish at 09:00 WAT on this date.', for: 'pub-d' }) + (pending.length ? `${alertBox('warn', `${pending.length} report${pending.length === 1 ? ' is' : 's are'} not approved yet in ${progs.length === 1 ? 'this programme' : 'these programmes'}`, 'They will be held back, not published, and listed under Held back until you approve them.')}${ck('pub-hold', 'Include them in this schedule (held until approved)', true)}` : '') : ''}
    <div class="card flat tight">${cs.map(c => `<div class="row small" style="padding:4px 0">${logo(S.orgs[c.org], 20)}<span class="grow">${esc(S.orgs[c.org].name)}</span><span class="cap muted">${esc(progOf(c.prog).name)}</span></div>`).join('')}</div>
    <div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn(mode === 'now' ? 'Publish' : 'Schedule', { act: 'pubGo', arg: mode, test: 'pub-go' })}</div></div>`, { wide: true }); };
function publishCase(c, by) { const p = progOf(c.prog); c.stage = 'Published'; c.published = '19 Oct 2026'; c.score = c.score ?? caseScore(c); c.opened = false; c.pubBy = by; (c.findings || []).forEach(f => { f.status = f.status || (fcOf(f.cls).days ? 'Open' : 'Noted'); }); progActivity(p, by, `published the report for ${S.orgs[c.org].name}`); notify({ ws: 'organisation', i: 'seal-check', tone: 'ok', title: `Your ${p.name} report is published`, go: 'org/report', arg: c.id, kind: 'Updates' }); }
ACT.pubGo = (mode) => {
  const cs = (S.ui.revSel || []).map(caseOf);
  if (mode === 'now') { cs.forEach(c => publishCase(c, persona().name)); addAudit('Published reports', `${cs.length} reports`); toast(`${cs.length} report${cs.length === 1 ? '' : 's'} published`, 'ok', 'paper-plane-tilt'); S.ui.revTab = 'published'; }
  else { const d = val('pub-d'); if (!d || d <= '2026-10-19') { toast('Choose a date after today', 'bad'); return; } const hold = val('pub-hold'); const progs = [...new Set(cs.map(c => c.prog))]; cs.forEach(c => { c.stage = 'Scheduled'; c.pubAt = d; }); let h = 0; if (hold) S.cases.filter(c => progs.includes(c.prog) && ['Report submitted', 'In review', 'Returned'].includes(c.stage)).forEach(c => { c.stage = 'Held back'; c.pubAt = d; c.holdReason = `Not approved when publishing was scheduled for ${fmtD(d)}`; h++; }); addAudit('Scheduled publishing', `${cs.length} reports for ${fmtD(d)}${h ? `; ${h} held back` : ''}`); toast(`${cs.length} scheduled for ${fmtD(d)}${h ? `. ${h} held back until approved.` : ''}`, 'ok', 'calendar-blank'); S.ui.revTab = h ? 'held' : 'scheduled'; }
  S.ui.revSel = []; closeDialog(); render();
};

/* ---------- Review a report ---------- */
screen('reviews/report', {
  t: 'Review report', layout: 'app', ws: 'regulator', crumbs: () => [['Reviews & publishing', 'reviews'], S.orgs[revCase().org].name],
  render() {
    const c = revCase(); const p = progOf(c.prog); const o = S.orgs[c.org]; const f = S.firms[c.firm]; const sch = schemeOf(p); const reqs = qsetReqs(p.qset); const sc = caseScore(c) ?? c.score;
    const canDecide = ['Report submitted', 'In review'].includes(c.stage); const held = c.stage === 'Held back';
    const ovN = Object.values(c.outcomes).filter(x => x.override).length;
    return `<div class="rh">${logo(o, 48)}<div class="rh-main"><div class="overline">${esc(p.name)}${f ? ' · ' + esc(f.name) : ''}</div><div class="rh-title"><h1 class="h1">${esc(o.name)}</h1>${statusChip(c.stage)}</div><div class="rh-meta">Signed off by ${esc((c.signed || {}).by || c.lead || 'the firm')}${c.reportAt ? ' · submitted ' + esc(c.reportAt) : ''}${c.reviewer ? ' · reviewer ' + esc(c.reviewer) : ''}</div></div></div>
      <div class="grid side"><div class="col gap16">
        <div class="card col gap12"><div class="row"><div class="grow"><div class="overline">Score</div><div class="row gap8" style="align-items:baseline"><span class="metric">${sc ?? '—'}</span><span class="small muted">${esc(bandOf(sch, sc))}</span>${ovN ? chip(`${ovN} outcome${ovN > 1 ? 's' : ''} changed by ${esc(S.tenant.short)}`, 'info', 'pencil-simple') : ''}</div></div>${outCounts(c, sch)}</div>
          ${p.qset.sections.filter(s => s.on).map(s => { const ss = caseScore(c, s.id); return `<div class="row small"><span class="grow">${esc(s.name)}</span><span style="width:260px">${progBar(ss || 0, ss == null ? '—' : ss)}</span></div>`; }).join('')}</div>
        <div class="card p0"><div class="tbl-tools"><span class="h4 grow">Outcomes</span><span class="cap muted">Change an outcome only with a reason. The firm and organisation see the change.</span></div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Requirement</th><th>Organisation said</th><th>Firm outcome</th><th>Note</th><th class="act-col"></th></tr></thead><tbody>${reqs.map(r => { const oc = c.outcomes[r.ref] || {}; const yn = r.questions.filter(q => q.choice === 'yn').map(q => (c.answers[q.id] || {}).v).filter(Boolean); return `<tr><td class="wrap"><span class="mono small" style="color:var(--brand-600)">${esc(r.ref)}</span> <span class="small">${esc(r.t)}</span></td><td class="small">${yn.length ? yn.map(v => chip(v, v === 'Yes' ? 'ok' : v === 'No' ? 'bad' : 'neu')).join(' ') : '—'}</td><td>${oc.o ? chip(oc.o, outTone(sch, oc.o)) : '—'}${oc.override ? `<div class="cap" style="color:var(--info-fg);margin-top:2px">Was ${esc(oc.override.from)} · ${esc(oc.override.by)}</div>` : ''}</td><td class="wrap small muted">${esc(oc.override ? oc.override.reason : oc.note || '')}</td><td class="act-col">${canDecide ? btn('Change', { v: 'tertiary', size: 'sm', act: 'ovDlg', arg: r.ref, test: 'ov-' + r.ref }) : ''}</td></tr>`; }).join('')}</tbody></table></div></div>
        ${(c.findings || []).length ? `<div class="card col gap8"><div class="h4">Findings</div>${c.findings.map(fd => `<div class="row small"><span class="chip ${fcOf(fd.cls).tone}">${esc(fd.cls)}</span><span class="grow">${esc(fd.title)}</span><span class="cap mono muted">${esc(fd.ref)}</span><span class="cap muted">${fd.due ? 'fix by ' + fmtD(fd.due) : ''}</span></div>`).join('')}</div>` : ''}
        ${(c.previewComments || []).length ? `<div class="card col gap8"><div class="h4">Organisation's comments on the preview</div>${c.previewComments.map(m => `<div class="oa"><div class="cap mono muted">${esc(m.ref)}</div><p class="small">“${esc(m.text)}”</p></div>`).join('')}</div>` : ''}</div>
      <div class="col gap16"><div class="card col gap12"><div class="h4">Decision</div>
        ${canDecide || held ? `${field('Reviewer', sel('rv-who', reviewers().map(t => [t.name, t.name]), c.reviewer || persona().name), { for: 'rv-who' })}${field('Note', ta('rv-note', '', { attrs: 'rows="2"', ph: 'Required if you return the report' }), { for: 'rv-note' })}
          ${btn('Approve report', { block: true, i: 'check-circle', act: 'revDecide', arg: 'approve', test: 'rv-approve' })}${held ? '' : btn('Return to firm', { v: 'secondary', block: true, i: 'arrow-u-up-left', act: 'revDecide', arg: 'return', test: 'rv-return' })}`
        : c.stage === 'Approved' ? `${alertBox('ok', 'Approved', `${esc((c.approved || {}).by || '')} · ${esc((c.approved || {}).when || '')}`)}${p.publisher === 'firm' ? note(`Publishing is delegated to ${esc(f ? f.name : 'the firm')} for this programme. You can still publish it yourself.`, 'info') : ''}${btn('Publish now', { block: true, i: 'paper-plane-tilt', act: 'pubOne', arg: c.id, test: 'pub-one' })}${btn('Schedule', { v: 'outline', block: true, i: 'calendar-blank', act: 'pubOneSched', arg: c.id })}`
        : c.stage === 'Scheduled' ? `${alertBox('info', `Publishes on ${fmtD(c.pubAt)}`, 'Organisations are emailed when it publishes.')}${btn('Cancel schedule', { v: 'outline', block: true, act: 'pubCancel', arg: c.id })}`
        : c.stage === 'Published' ? alertBox('ok', 'Published ' + esc(c.published || ''), c.opened ? 'The organisation has opened it.' : 'Not opened yet.')
        : c.stage === 'Returned' ? alertBox('warn', 'Returned to the firm', esc(c.returnNote || '')) : note('Waiting for the firm.', 'hourglass')}</div>
        <div class="card col gap8"><div class="h4">Engagement</div>${kv([['Firm', esc(f ? f.name : '—')], ['Lead auditor', esc(c.lead || '—')], ['Quality review', esc(c.qr ? c.qr.by : '—')], ['Organisation submitted', esc(c.submitted || '—')]])}</div></div></div>`;
  }
});
ACT.ovDlg = (ref) => { const c = revCase(); const sch = schemeOf(progOf(c.prog)); const oc = c.outcomes[ref] || {}; openDialog(`${dlgHead('Change outcome', `${esc(ref)} · the firm said ${esc(oc.o || 'nothing')}`, 'pencil-simple')}<form class="col gap12" data-form="ov" data-arg="${ref}"><div class="oc-pick">${sch.levels.map(([l, , tn]) => `<label class="oc-o ${tn}"><input type="radio" name="ov-o" value="${esc(l)}">${esc(l)}</label>`).join('')}</div>${field('Reason', ta('ov-r', '', { attrs: 'rows="2"', ph: 'Why NITDA disagrees with the firm' }), { for: 'ov-r' })}<div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Change outcome', { type: 'submit', test: 'ov-go' })}</div></form>`); setTimeout(() => $$('#dlg .oc-o').forEach(l => l.addEventListener('click', () => { $$('#dlg .oc-o').forEach(x => x.classList.remove('on')); l.classList.add('on'); }))); };
ACT.form_ov = (f) => { const v = ($$('input[name=ov-o]').find(x => x.checked) || {}).value; const r = val('ov-r'); if (!v || !r) { toast('Choose an outcome and give a reason', 'bad'); return; } const c = revCase(); const oc = c.outcomes[f.dataset.arg] || {}; c.outcomes[f.dataset.arg] = Object.assign({}, oc, { o: v, override: { from: oc.o || '—', reason: r, by: persona().name } }); if (c.stage === 'Report submitted') { c.stage = 'In review'; c.reviewer = c.reviewer || persona().name; } addAudit('Changed outcome', `${S.orgs[c.org].name} · ${f.dataset.arg}: ${oc.o} → ${v}`); notify({ ws: 'firm', i: 'pencil-simple', tone: 'info', title: `${S.tenant.short} changed an outcome for ${S.orgs[c.org].name}`, go: 'firm/engagements', kind: 'Updates' }); closeDialog(); render(); toast('Outcome changed. Score updated.'); };
ACT.revDecide = (d) => { const c = revCase(); const n = val('rv-note'); if (d === 'return' && !n) { toast('Say what the firm should fix', 'bad'); return; } const p = progOf(c.prog); c.reviewer = val('rv-who') || c.reviewer;
  if (d === 'approve') { c.approved = { by: persona().name, when: '19 Oct 2026' }; c.score = caseScore(c) ?? c.score; if (c.stage === 'Held back') { c.stage = 'Scheduled'; c.holdReason = ''; toast(`Approved. It will publish with the rest on ${fmtD(c.pubAt)}.`); } else { c.stage = 'Approved'; toast('Report approved'); } progActivity(p, persona().name, `approved the report for ${S.orgs[c.org].name}`); notify({ ws: 'firm', i: 'check-circle', tone: 'ok', title: `${S.tenant.short} approved your report for ${S.orgs[c.org].name}`, go: 'firm/engagements', kind: 'Updates' }); }
  else { c.stage = 'Returned'; c.returnNote = n; c.signed = null; c.qr = null; progActivity(p, persona().name, `returned the report for ${S.orgs[c.org].name}`); notify({ ws: 'firm', i: 'arrow-u-up-left', tone: 'warn', title: `${S.tenant.short} returned your report for ${S.orgs[c.org].name}`, go: 'firm/engagements', kind: 'Approvals' }); toast('Returned to the firm', 'info'); }
  addAudit(d === 'approve' ? 'Approved report' : 'Returned report', `${S.orgs[c.org].name} · ${p.name}`); render(); };
ACT.pubOne = (id) => { const c = caseOf(id); publishCase(c, persona().name); addAudit('Published report', S.orgs[c.org].name); render(); toast('Published. The organisation is emailed.', 'ok', 'paper-plane-tilt'); };
ACT.pubOneSched = (id) => { S.ui.revSel = [id]; ACT.pubDlg('schedule'); };
ACT.pubCancel = (id) => { const c = caseOf(id); c.stage = 'Approved'; c.pubAt = ''; render(); toast('Schedule cancelled'); };

/* Firm: delegated publishing (approved reports only) */
ACT.firmPublish = (id) => { const c = caseOf(id); if (c.stage !== 'Approved' || progOf(c.prog).publisher !== 'firm') { toast('Only approved reports in delegated programmes can be published by the firm', 'bad'); return; } openDialog(`${dlgHead('Publish this report?', `${esc(S.orgs[c.org].name)} · ${esc(progOf(c.prog).name)}. ${esc(S.tenant.short)} approved it and delegated publishing to your firm.`, 'paper-plane-tilt')}<div class="row end">${btn('Cancel', { v: 'outline', act: 'closeDialog' })}${btn('Publish', { act: 'firmPublishGo', arg: id, test: 'fp-go' })}</div>`); };
ACT.firmPublishGo = (id) => { const c = caseOf(id); publishCase(c, myFirm().name); addAudit('Published report (delegated)', `${S.orgs[c.org].name} · ${myFirm().name}`); notify({ ws: 'regulator', i: 'paper-plane-tilt', tone: 'info', title: `${myFirm().name} published the report for ${S.orgs[c.org].name}`, go: 'reviews', arg: 'published', kind: 'Updates' }); closeDialog(); render(); toast('Published', 'ok', 'paper-plane-tilt'); };

/* ---------- Organisation: My report ---------- */
OPEN_HOOKS['org/report'] = (id) => { S.ui.repId = id; };
ACT.openReport = (id) => openRoute('org/report', id);
screen('org/report', {
  t: 'Report', layout: 'app', ws: 'organisation', crumbs: () => { const c = caseOf(S.ui.repId) || myCases().find(x => x.stage === 'Published'); return [['Obligations', 'org/obligations'], c ? progOf(c.prog).name : 'Report']; },
  render() {
    const c = caseOf(S.ui.repId) || myCases().find(x => x.stage === 'Published');
    if (!c || c.stage !== 'Published') return `${pageHead({ title: 'Report' })}<div class="card">${empty('file-text', 'No published report', 'Reports appear here when ' + esc(S.tenant.short) + ' publishes them.')}</div>`;
    if (!c.opened) { c.opened = true; c.openedAt = '19 Oct 2026'; }
    const p = progOf(c.prog); const sch = schemeOf(p); const reqs = qsetReqs(p.qset); const sc = c.score ?? caseScore(c); const f = S.firms[c.firm];
    return `<div class="rep-hero"><div class="grow"><div class="overline" style="color:var(--brand-200)">Published ${esc(c.published || '')} · ${esc(p.name)}</div><h1 class="serif">${esc(S.orgs[c.org].name)}</h1><p>Assessed by ${esc(f ? f.name : '—')}. Approved by ${esc(S.tenant.short)}.</p></div><div class="rep-score"><span>${sc ?? '—'}</span><b>${esc(bandOf(sch, sc))}</b></div></div>
      <div class="grid side"><div class="col gap16"><div class="card col gap12"><div class="h4">By section</div>${p.qset.sections.filter(s => s.on).map(s => { const ss = caseScore(c, s.id); return `<div class="row small"><span class="grow">${esc(s.name)}</span><span style="width:280px">${progBar(ss || 0, ss == null ? '—' : ss)}</span></div>`; }).join('')}</div>
        <div class="card p0"><div class="tbl-tools"><span class="h4 grow">Outcomes</span>${outCounts(c, sch)}</div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Requirement</th><th>Outcome</th><th>Assessor note</th></tr></thead><tbody>${reqs.map(r => { const oc = c.outcomes[r.ref] || {}; return `<tr><td class="wrap"><span class="mono small" style="color:var(--brand-600)">${esc(r.ref)}</span> <span class="small">${esc(r.t)}</span></td><td>${oc.o ? chip(oc.o, outTone(sch, oc.o)) : '—'}</td><td class="wrap small muted">${esc(oc.override ? oc.override.reason : oc.note || '')}</td></tr>`; }).join('')}</tbody></table></div></div></div>
      <div class="col gap16"><div class="card col gap8"><div class="row"><span class="h4 grow">Findings</span>${count((c.findings || []).length)}</div>${(c.findings || []).map(fd => `<div class="row small top"><span class="chip ${fcOf(fd.cls).tone}">${esc(fd.cls)}</span><div class="grow"><div>${esc(fd.title)}</div><div class="cap muted">${esc(fd.ref)}${fd.due ? ' · fix by ' + fmtD(fd.due) : ''}</div></div></div>`).join('') || '<p class="small muted">No findings.</p>'}${(c.findings || []).length && SCREENS['org/findings'] ? btn('Plan your fixes', { v: 'secondary', size: 'sm', go: 'org/findings', test: 'to-findings' }) : ''}</div>
        ${typeof rateCard === 'function' ? rateCard(c) : ''}<div class="card col gap8">${btn('Download report (PDF)', { v: 'outline', block: true, i: 'download-simple', act: 'savedToast', arg: 'Report downloaded' })}<p class="cap muted">The report and your answers are kept for 7 years.</p></div></div></div>`;
  }
});

